"""Python port vs. the reference results used by the Swift tests (generated by the original DexWorld Python engine).

Run:  python3 -m unittest discover -s python/tests -v
"""
import base64
import json
import os
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
sys.path.insert(0, os.path.join(ROOT, "python"))
import subautosync as S  # noqa: E402

FIX = os.path.join(ROOT, "Tests", "SubtitleAutoSyncTests", "Fixtures")


def load(name):
    with open(os.path.join(FIX, name), encoding="utf-8") as f:
        return json.load(f)


class Parity(unittest.TestCase):
    def test_alignment(self):
        bad = []
        cases = load("align_cases.json")
        self.assertGreater(len(cases), 200)
        for c in cases:
            got = S.align(c["ref"], c["sub"])
            e = c["res"]
            d = []
            if "reason" in e and e["reason"]:
                if got.reason != e["reason"]:
                    d.append("reason")
            else:
                if abs(got.scale - e["scale"]) > 1e-12 * max(1, abs(e["scale"])):
                    d.append(f"scale {got.scale} {e['scale']}")
                for k, g in (("offset_ms", got.offset_ms), ("hits", got.hits), ("total", got.total),
                             ("max_move_ms", got.max_move_ms)):
                    if g != e[k]:
                        d.append(f"{k} {g} {e[k]}")
                if abs(got.rival - e["rival"]) > 1e-12:
                    d.append("rival")
            if S.decide(got, 0.45) != c["decision"]:
                d.append("decision")
            if d:
                bad.append((c["id"], c["kind"], d))
        self.assertEqual(bad, [])

    def test_segment_check(self):
        bad = []
        for c in load("segment_cases.json"):
            r = S.Alignment(scale=c["res"]["scale"], offset_ms=c["res"]["offset_ms"])
            ok, segs = S.segment_check(c["ref"], c["sub"], r)
            d = [] if ok == c["ok"] else ["ok"]
            for i, exp in enumerate(c["details"]):
                g = segs[i] if i < len(segs) else None
                if isinstance(exp, list):
                    if g is None:
                        d.append(f"seg{i} missing")
                        continue
                    if round(g[0], 2) != exp[0] or round(g[1], 2) != exp[1] or g[2] != exp[2]:
                        d.append(f"seg{i} {g} {exp}")
                elif g is not None:
                    d.append(f"seg{i} should be None")
            if d:
                bad.append((c["id"], c["kind"], d))
        self.assertEqual(bad, [])

    def test_parse_and_rewrite_byte_exact(self):
        for c in load("subs_cases.json"):
            name = c["name"]
            with open(os.path.join(FIX, "subs", name), "rb") as f:
                raw = f.read()
            self.assertEqual(S.detect_kind(raw, name), c["kind"], name)
            self.assertEqual(S.parse_starts(raw, name), c["starts"], name)
            for o in c["outputs"]:
                got = S.apply_transform(raw, o["scale"], o["offset_ms"], name)
                self.assertEqual(got, base64.b64decode(o["b64"]), f"{name} {o['scale']} {o['offset_ms']}")

    def test_mkv_cues_reader(self):
        for file, e in sorted(load("cues_cases.json").items()):
            path = os.path.join(FIX, "media", file)
            src = S._FileSource(path, S._Budget())
            reader = S.MatroskaCues(src)
            try:
                tracks = reader.load()
                ok, reason = True, None
            except S.ReferenceError_ as err:
                tracks, ok, reason = [], False, err.reason
            self.assertEqual(ok, e["ok"], file)
            self.assertEqual(reason, e.get("reason"), file)
            self.assertEqual(src.budget.bytes, e["stats"]["bytes"], file + " bytes")
            self.assertEqual(src.budget.requests, e["stats"]["requests"], file + " requests")
            if not ok:
                continue
            self.assertEqual(reader.via, e.get("via"), file)
            self.assertEqual(len(tracks), len(e["tracks"]))
            for t, x in zip(tracks, e["tracks"]):
                self.assertEqual(t.number, x["number"])
                self.assertEqual(t.codec, x["codec"])
                self.assertEqual(t.lang, x["lang"])
                self.assertEqual(t.forced, x["forced"])
                self.assertEqual(t.hi, x["hi"])
                self.assertEqual(t.commentary, x["commentary"])
                self.assertEqual(t.is_default, x["default"])
                self.assertEqual(t.starts, [q[0] for q in x["cues"]], f"{file} #{t.number}")
            picked = S.pick_reference(tracks)
            self.assertEqual(picked.number if picked else None, e.get("picked"), file)

    def test_timestamp_helpers(self):
        self.assertEqual(S.timestamp_ms("01:02:03,456"), 3_723_456)
        self.assertEqual(S.timestamp_ms("02:03.4"), 123_400)
        self.assertEqual(S.timestamp_ms("0:00:01:50"), 1500)
        self.assertEqual(S.format_ts(1995, "0:00:00.00", "ass"), "0:00:02.00")
        self.assertEqual(S.format_ts(61_005, "01:00.000", "pair"), "01:01.005")
        self.assertEqual(S.format_ts(3_600_000, "59:59.999", "pair"), "01:00:00.000")


class EndToEnd(unittest.TestCase):
    """Build a 25 fps subtitle from the reference and run the CLI on the real MKV fixtures."""

    @classmethod
    def setUpClass(cls):
        with open(os.path.join(FIX, "media", "ref_en.srt"), "rb") as f:
            cls.ref_raw = f.read()
        cls.starts = S.parse_starts(cls.ref_raw, "ref_en.srt")

    def make(self, shift=0, scale=1.0, cut_at=None, cut_shift=0):
        a0, a1 = self.starts[0], self.starts[-1]
        out = []
        for i, s in enumerate(self.starts):
            t = int(s * scale) + shift
            if cut_at is not None and (s - a0) > (a1 - a0) * cut_at:
                t += cut_shift
            out.append(f"{i + 1}\n{S.format_ts(t, '00:00:00,000', 'pair')} --> "
                       f"{S.format_ts(t + 1500, '00:00:00,000', 'pair')}\nline {i}\n")
        return "\n".join(out).encode()

    def test_cli_mkv_offset_and_fps(self):
        import tempfile
        mkv = os.path.join(FIX, "media", "multi.mkv")
        with tempfile.TemporaryDirectory() as d:
            p = os.path.join(d, "x.ar.srt")
            with open(p, "wb") as f:
                f.write(self.make(scale=25 / 23.976, shift=2500))
            self.assertEqual(S.main([mkv, p, "--json"]), 0)
            with open(p.replace(".srt", ".synced.srt"), "rb") as f:
                fixed = S.parse_starts(f.read())
            close = sum(1 for a, b in zip(fixed, self.starts) if abs(a - b) <= 2)
            self.assertGreater(close, len(self.starts) * 0.95)

    def test_different_cut_rejected(self):
        o = S.synchronize(self.make(shift=-2000, cut_at=0.7, cut_shift=-5000), "d.srt", self.starts)
        self.assertEqual(o.status, "different_cut")

    def test_already_in_sync(self):
        o = S.synchronize(self.make(shift=50), "s.srt", self.starts)
        self.assertEqual(o.status, "in_sync")

    def test_messages(self):
        o = S.synchronize(self.make(shift=6500), "a.srt", self.starts)
        self.assertEqual(S.describe(o, "en"), "✅ Synced: moved 6.5 s earlier (100% matched)")
        self.assertEqual(S.describe(o, "ar"), "✅ تمت المزامنة: تم تقديم الترجمة 6.5 ثانية (تطابق 100%)")


if __name__ == "__main__":
    unittest.main()
